import { AppShell, Button, ConsentCheckbox, Field } from "@wizard/ui-kit";
import { useEntityMutation, useState } from "@wizard/sdk";

export default function Main() {
  const [form, setForm] = useState({ name: "", phone: "", consent: false });
  const requests = useEntityMutation("request");
  return (
    <AppShell title={"Онбординг новых сотрудников по чек-листам"}>
      <p>{"Сеть из трёх кофеен и офис, в год выходит около сорока новых сотрудников. Онбординг держится на памяти управляющих: кому-то забывают выдать форму, кто-то неделю работает без доступа к кассе. Нужен сервис онбординга: HR заводит нового сотрудника (должность, точка, дата выхода, руководитель, наставник), и система создаёт чек-лист по шаблону должности. В шаблоне задачи с ответственным (HR, руководитель, наставник, сам новичок) и сроком относительно даты выхода: «за 3 дня — заказать форму», «в первый день — вводный инструктаж», «на второй неделе — аттестация по меню». Каждый видит свои задачи и отмечает выполнение, к задаче можно приложить фото или комментарий. Просроченные задачи подсвечиваются, ответственный и HR получают уведомление в Telegram. Новичок видит свой план адаптации и проходит короткий тест по стандартам с вопросами от HR. Паспортные данные и сканы в системе не собираем — это делает бухгалтерия отдельно. HR видит прогресс по всем новичкам и отчёт: сколько дней в среднем занимает онбординг и где чаще всего просрочки."}</p>
      <ul>
        <li>{"Чек-лист по шаблону должности"}</li>
        <li>{"Срок относительно даты выхода"}</li>
        <li>{"Отметка выполнения"}</li>
        <li>{"Фото или комментарий к задаче"}</li>
        <li>{"Уведомления о просрочке в Telegram"}</li>
        <li>{"Тест по стандартам"}</li>
        <li>{"Отчёт по срокам онбординга"}</li>
      </ul>
      <p>{"Чек-лист создаётся автоматически при заведении сотрудника"}</p>
      <p>{"Ответственный видит только свои задачи"}</p>
      <p>{"Просроченная задача вызывает уведомление"}</p>
      <p>{"Новичок видит свой план адаптации"}</p>
      <form onSubmit={(e) => { e.preventDefault(); void requests.create({ contact_name: form.name, contact_phone: form.phone }, { consent: true }); }}>
        <Field name="contact_name" label="Имя" type="string" value={form.name} onChange={(v) => setForm({ ...form, name: String(v) })} />
        <Field name="contact_phone" label="Телефон" type="phone" value={form.phone} onChange={(v) => setForm({ ...form, phone: String(v) })} />
        <ConsentCheckbox checked={form.consent} onChange={(v) => setForm({ ...form, consent: v })} />
        <Button type="submit">{"Отправить заявку"}</Button>
      </form>
    </AppShell>
  );
}
